package com.dat.ai_receptionist_web.service.Finance;
import com.dat.ai_receptionist_web.dto.*; import com.dat.ai_receptionist_web.dto.Finance.EnrollmentAddonPurchaseDTO; import com.dat.ai_receptionist_web.error.*; import com.dat.ai_receptionist_web.error.code.FinanceErrorCode; import com.dat.ai_receptionist_web.mapper.Finance.EnrollmentAddonPurchaseMapper; import com.dat.ai_receptionist_web.repository.Finance.EnrollmentAddonPurchaseRepository; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class EnrollmentAddonPurchaseService { private final EnrollmentAddonPurchaseRepository repository; private final EnrollmentAddonPurchaseMapper mapper; @Transactional(readOnly=true) public PageResponse<EnrollmentAddonPurchaseDTO.SimpleResponse> list(UUID enrollmentId,UUID addonId,Pageable pageable){return PageResponse.of(repository.findAllDetailed(enrollmentId,addonId,pageable),mapper::toSimpleResponse);} @Transactional(readOnly=true) public EnrollmentAddonPurchaseDTO.Response get(UUID id){return mapper.toResponse(repository.findDetailedById(id).orElseThrow(()->new ApiException(FinanceErrorCode.ENROLLMENT_ADDON_PURCHASE_NOT_FOUND)));} }
